import random, math
random.seed(0); N=40000; K=28
def trial(m):
    for _ in range(m):
        s=0.0
        for k in range(1,K+1):
            s+=random.gauss(0,1)
            if s/math.sqrt(k)>1.96: return 1
    return 0
for m in (1,8): print(m,'metric(s):', sum(trial(m) for _ in range(N))/N)
