import random,math
random.seed(0)
N=20000; days=28
res={1.96:[0,0],1.645:[0,0]}
for _ in range(N):
    s=[0.0]*8; hit={1.96:[False,False],1.645:[False,False]}
    for d in range(1,days+1):
        for m in range(8):
            s[m]+=random.gauss(0,1)
            z=s[m]/math.sqrt(d)
            for t in res:
                if z>t:
                    hit[t][1]=True
                    if m==0: hit[t][0]=True
    for t in res:
        res[t][0]+=hit[t][0]; res[t][1]+=hit[t][1]
for t in res: print(t, 'one metric', res[t][0]/N, 'eight independent', res[t][1]/N)
"
